<nav class="attention-pagination ct-pagination" aria-label="{{ $label }}" x-cloak x-show="!loading && !error && meta.total > 0">
    <x-page-size /><span class="ct-page-count" x-text="`Showing ${(page-1)*perPage+1}–${Math.min(page*perPage,meta.total)} of ${meta.total}`"></span><button type="button" class="ct-secondary" @click="load(page - 1)" :disabled="loading || page <= 1" aria-label="Previous page">‹</button><span class="ct-page-current" x-text="page"></span><button type="button" class="ct-secondary" @click="load(page + 1)" :disabled="loading || page >= meta.lastPage" aria-label="Next page">›</button><span x-text="`Page ${page} of ${meta.lastPage || 1}`"></span>
</nav>
